// Unwip - Build › Insignia. Emblems for corporations, gangs, units and guilds in cyberpunk and sci-fi stories: a hard
// frame (hexagon, chevron, roundel…), one simple line symbol, two flat colours and an accent, and a name with a
// designation underneath. The symbols are plain single-line drawings made in code; nothing here is generated by AI.
(function () {
  'use strict';
  const B = window.UnwipBuild; if (!B) return;
  const U = window.__unwip;
  const { $, $$, esc } = U;

  // ---- colours: background, main line, accent
  const SCHEMES = {
    neon: { name: 'Neon', bg: '#0b0f17', main: '#e6f1ff', acc: '#ff2e88' },
    corp: { name: 'Corporate', bg: '#f1f1ee', main: '#14171b', acc: '#00a0c0' },
    military: { name: 'Military', bg: '#1b1d17', main: '#d6c27c', acc: '#e2532f' },
    toxic: { name: 'Toxic', bg: '#0c110a', main: '#b6ff3a', acc: '#eaeaea' },
    blood: { name: 'Blood', bg: '#140909', main: '#f2ebe4', acc: '#d61f30' },
    chrome: { name: 'Chrome', bg: '#17191d', main: '#c9ced6', acc: '#f2c84b' },
    ice: { name: 'Ice', bg: '#08131c', main: '#9fe6ff', acc: '#ffffff' }
  };
  const FRAMES = { hex: 'Hexagon', chevron: 'Chevron', roundel: 'Roundel', badge: 'Badge', diamond: 'Diamond', notched: 'Notched ring', none: 'No frame' };
  // ---- the symbols: single lines in a 100 × 100 box centred on 0,0 (stroke only, so they take the line weight)
  const SYM = {
    eye: ['Eye', 'M-42 0Q0-34 42 0Q0 34-42 0Z M0 0m-12 0a12 12 0 1 0 24 0a12 12 0 1 0-24 0'],
    skull: ['Skull', 'M-30 8C-38-30 38-30 30 8L22 16V30H-22V16Z M-14 0m-7 0a7 7 0 1 0 14 0a7 7 0 1 0-14 0 M14 0m-7 0a7 7 0 1 0 14 0a7 7 0 1 0-14 0 M-8 30V20M0 30V20M8 30V20'],
    bolt: ['Lightning', 'M8-44L-22 6H2L-8 44L24-8H0Z'],
    star: ['Star', 'M0-42L10-13H40L16 5L25 34L0 17L-25 34L-16 5L-40-13H-10Z'],
    crown: ['Crown', 'M-38 22L-38-20L-19 0L0-30L19 0L38-20L38 22Z M-38 34H38'],
    wings: ['Wings', 'M-6 10L-44-18M-6 20L-40 2M-6 30L-32 20 M6 10L44-18M6 20L40 2M6 30L32 20 M0 0V38'],
    dagger: ['Blade', 'M0-46L8-20V16H-8V-20Z M-20 16H20 M0 16V40 M-6 44H6'],
    crosshair: ['Crosshair', 'M0 0m-28 0a28 28 0 1 0 56 0a28 28 0 1 0-56 0 M0-44V-14M0 14V44M-44 0H-14M14 0H44'],
    chip: ['Chip', 'M-24-24H24V24H-24Z M-12-12H12V12H-12Z M-14-24V-38M0-24V-38M14-24V-38M-14 24V38M0 24V38M14 24V38M-24-14H-38M-24 0H-38M-24 14H-38M24-14H38M24 0H38M24 14H38'],
    serpent: ['Serpent', 'M-30 38C-50 20-10 10 0 0S40-24 20-40 M20-40L30-36M20-40L22-30'],
    key: ['Key', 'M-20-20m-16 0a16 16 0 1 0 32 0a16 16 0 1 0-32 0 M-9-9L36 36M22 22L30 14M30 30L38 22'],
    flame: ['Flame', 'M0 42C-30 42-34 10-16-10C-14 4-6 6-6 6C-12-14 0-30 6-44C10-26 32-14 30 12C28 32 16 42 0 42Z'],
    sun: ['Sun', 'M0 0m-16 0a16 16 0 1 0 32 0a16 16 0 1 0-32 0 M0-26V-42M0 26V42M-26 0H-42M26 0H42M-18-18L-30-30M18 18L30 30M-18 18L-30 30M18-18L30-30'],
    moon: ['Moon', 'M14-36A38 38 0 1 0 14 36A30 30 0 1 1 14-36Z'],
    spear: ['Spearhead', 'M0-44L18 0L6 0V40H-6V0L-18 0Z'],
    triangle: ['Triangle', 'M0-40L38 30H-38Z M0 6m-6 0a6 6 0 1 0 12 0a6 6 0 1 0-12 0'],
    atom: ['Orbit', 'M0 0m-4 0a4 4 0 1 0 8 0a4 4 0 1 0-8 0 M-42 0A42 14 0 1 0 42 0A42 14 0 1 0-42 0 M-21-36A42 14 60 1 0 21 36A42 14 60 1 0-21-36'],
    pulse: ['Pulse', 'M-46 4H-20L-12-18L-2 30L8-30L16 4H46'],
    hourglass: ['Hourglass', 'M-24-40H24M-24 40H24M-18-40C-18-12 18-12 18-40M-18 40C-18 12 18 12 18 40M-18-40V-40M0-14V14'],
    cog: ['Cog', 'M0 0m-14 0a14 14 0 1 0 28 0a14 14 0 1 0-28 0 M-6-40H6L8-28L18-24L28-32L34-26L28-16L32-6L42-4V8L32 8L28 18L34 26L26 34L18 28L8 32L6 42H-6L-8 32L-18 28L-26 34L-34 26L-28 18L-32 8L-42 8V-4L-32-6L-28-16L-34-26L-28-32L-18-24L-8-28Z'],
    claw: ['Claw marks', 'M-30-40C-20-10-24 20-32 40M-6-44C4-12 0 20-8 44M18-40C28-10 24 20 16 40'],
    swords: ['Crossed blades', 'M-36-36L28 28M36-36L-28 28 M18 34L34 18M-18 34L-34 18 M28 28L38 38M-28 28L-38 38'],
    anchor: ['Anchor', 'M0-34m-7 0a7 7 0 1 0 14 0a7 7 0 1 0-14 0 M0-27V40 M-16-14H16 M-34 14C-30 34-10 40 0 40C10 40 30 34 34 14 M-34 14L-40 22M34 14L40 22'],
    antenna: ['Signal', 'M0 44V-6 M-14 44L0-6L14 44 M0-14m-5 0a5 5 0 1 0 10 0a5 5 0 1 0-10 0 M-16-28A22 22 0 0 1 16-28 M-26-38A36 36 0 0 1 26-38'],
    rook: ['Tower', 'M-26 40H26M-20 40L-16-14H16L20 40M-22-14V-38H-12V-28H-4V-38H4V-28H12V-38H22V-14'],
    infinity: ['Loop', 'M0 0C-12-18-40-18-40 0S-12 18 0 0S40-18 40 0S12 18 0 0Z'],
    stack: ['Chevrons', 'M-36-10L0-36L36-10M-36 10L0-16L36 10M-36 30L0 4L36 30'],
    hand: ['Open hand', 'M-22 40V0L-30-16M-22 0V-26M-8-4V-38M6-4V-36M20 0V-26M20 0V18C20 32 10 40-4 40H-22']
  };
  const SYM_KEYS = Object.keys(SYM);
  const blank = () => ({ frame: 'hex', symbol: 'eye', scheme: 'neon', name: '', desig: '', code: '', weight: 5, panel: true, ticks: true, double: true, custom: null });
  const COND = "'Bahnschrift SemiCondensed', Bahnschrift, 'DIN Condensed', 'Avenir Next Condensed', 'Roboto Condensed', 'Arial Narrow', sans-serif";
  const colours = d => Object.assign({}, SCHEMES[d.scheme] || SCHEMES.neon, d.custom || {});

  // ---- the frames, around a centre of 200,200
  function poly(n, r, rot) { const p = []; for (let i = 0; i < n; i++) { const a = rot + i * 2 * Math.PI / n; p.push(`${(200 + r * Math.cos(a)).toFixed(1)},${(200 + r * Math.sin(a)).toFixed(1)}`); } return p.join(' '); }
  function frameSVG(d, C) {
    const w = d.weight, s = `fill="none" stroke="${C.main}" stroke-width="${w}" stroke-linejoin="miter"`, a = `fill="none" stroke="${C.acc}" stroke-width="${Math.max(1.5, w * 0.5)}"`;
    const ticks = (r, n, len) => { let t = ''; for (let i = 0; i < n; i++) { const q = i * 2 * Math.PI / n; t += `M${(200 + r * Math.cos(q)).toFixed(1)} ${(200 + r * Math.sin(q)).toFixed(1)}L${(200 + (r - len) * Math.cos(q)).toFixed(1)} ${(200 + (r - len) * Math.sin(q)).toFixed(1)}`; } return `<path d="${t}" ${a}/>`; };
    switch (d.frame) {
      case 'hex': return `<polygon points="${poly(6, 172, -Math.PI / 2)}" ${s}/>${d.double ? `<polygon points="${poly(6, 150, -Math.PI / 2)}" ${a}/>` : ''}${d.ticks ? `<path d="M200 28V48M200 352V372" ${a}/>` : ''}`;
      case 'chevron': return `<polygon points="40,52 200,92 360,52 360,250 200,370 40,250" ${s}/>${d.double ? `<polygon points="62,80 200,114 338,80 338,240 200,343 62,240" ${a}/>` : ''}${d.ticks ? `<path d="M40 150H62M338 150H360" ${a}/>` : ''}`;
      case 'roundel': return `<circle cx="200" cy="200" r="172" ${s}/>${d.double ? `<circle cx="200" cy="200" r="148" ${a}/>` : ''}${d.ticks ? ticks(172, 36, 12) : ''}`;
      case 'badge': return `<polygon points="70,30 330,30 370,70 370,330 330,370 70,370 30,330 30,70" ${s}/>${d.double ? `<polygon points="82,52 318,52 348,82 348,318 318,348 82,348 52,318 52,82" ${a}/>` : ''}${d.ticks ? `<path d="M30 200H50M350 200H370M200 30V50M200 350V370" ${a}/>` : ''}`;
      case 'diamond': return `<polygon points="200,22 378,200 200,378 22,200" ${s}/>${d.double ? `<polygon points="200,54 346,200 200,346 54,200" ${a}/>` : ''}${d.ticks ? `<path d="M200 22V40M200 360V378M22 200H40M360 200H378" ${a}/>` : ''}`;
      case 'notched': { let p = ''; const n = 8, r = 168, gap = 0.14; for (let i = 0; i < n; i++) { const a0 = i * 2 * Math.PI / n + gap, a1 = (i + 1) * 2 * Math.PI / n - gap; p += `M${(200 + r * Math.cos(a0)).toFixed(1)} ${(200 + r * Math.sin(a0)).toFixed(1)}A${r} ${r} 0 0 1 ${(200 + r * Math.cos(a1)).toFixed(1)} ${(200 + r * Math.sin(a1)).toFixed(1)}`; }
        return `<path d="${p}" ${s} stroke-linecap="butt"/>${d.double ? `<circle cx="200" cy="200" r="146" ${a}/>` : ''}${d.ticks ? ticks(184, 8, 16) : ''}`; }
      default: return '';
    }
  }
  function insigniaSVG(d, size) {
    const C = colours(d), sym = SYM[d.symbol] || SYM.eye, hasText = !!(d.name || d.desig || d.code), H = hasText ? 520 : 400;
    const k = d.frame === 'none' ? 3 : d.frame === 'chevron' ? 2 : 2.15, cy = d.frame === 'chevron' ? 200 : 200;
    const symW = d.weight * 0.95 / k;
    const nm = esc((d.name || '').toUpperCase()), dg = esc((d.desig || '').toUpperCase()), cd = esc((d.code || '').toUpperCase());
    // long names are squeezed to fit rather than running off the edge
    const L = (d.name || '').length, fs = L > 16 ? 32 : 40, ls = L > 16 ? 3 : 6;
    const fit = (n, f, sp, max) => n * (f * 0.56 + sp) > max ? ` textLength="${max}" lengthAdjust="spacingAndGlyphs"` : '';
    const text = hasText ? `<text x="200" y="${d.desig ? 450 : 462}" text-anchor="middle" font-family="${COND}" font-weight="700" font-size="${fs}" letter-spacing="${ls}"${fit(nm.length, fs, ls, 350)} fill="${C.main}">${nm}</text>
      ${dg ? `<path d="M40 482H${200 - Math.min(150, dg.length * 6.5)}M${200 + Math.min(150, dg.length * 6.5)} 482H360" stroke="${C.acc}" stroke-width="2"/><text x="200" y="488" text-anchor="middle" font-family="${COND}" font-size="17" letter-spacing="4"${fit((d.desig || '').length, 17, 4, 300)} fill="${C.acc}">${dg}</text>` : ''}
      ${cd ? `<text x="372" y="512" text-anchor="end" font-family="Menlo, Consolas, monospace" font-size="12" letter-spacing="2" fill="${C.main}" opacity=".6">${cd}</text>` : ''}` : '';
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 ${H}" width="${size}" height="${Math.round(size * H / 400)}">
      ${d.panel ? `<rect width="400" height="${H}" fill="${C.bg}"/>` : ''}
      ${frameSVG(d, C)}
      <g transform="translate(200 ${cy}) scale(${k})"><path d="${sym[1]}" fill="none" stroke="${C.main}" stroke-width="${symW}" stroke-linejoin="round" stroke-linecap="round"/></g>
      ${text}</svg>`;
  }
  const symIcon = (k, col) => `<svg viewBox="-52 -52 104 104" width="34" height="34"><path d="${SYM[k][1]}" fill="none" stroke="${col}" stroke-width="5" stroke-linejoin="round" stroke-linecap="round"/></svg>`;
  const rnd = a => a[Math.floor(Math.random() * a.length)];

  // ================================================================== THE EDITOR
  let it = null, ctx = null, box = null;
  function open(item, el, c) {
    it = item; ctx = c; box = el;
    it.data = Object.assign(blank(), it.data || {});
    if (!it.data.name && it.title && it.title !== 'Untitled') it.data.name = it.title;
    c.extra.innerHTML = '<button class="btn small" id="in-rand" title="Roll a random frame, symbol and colours (dice, not AI)">🎲 Random</button>';
    $('#in-rand', c.extra).onclick = () => { const d = it.data; d.frame = rnd(Object.keys(FRAMES).filter(f => f !== 'none')); d.symbol = rnd(SYM_KEYS); d.scheme = rnd(Object.keys(SCHEMES)); d.custom = null; d.double = Math.random() < 0.6; d.ticks = Math.random() < 0.6; save(); draw(); };
    draw(); wire();
  }
  const save = () => ctx.changed();
  function draw() {
    const d = it.data, C = colours(d);
    box.innerHTML = `<div class="in-page">
      <div class="in-left"><div class="in-shot" id="in-shot"></div>
        <p class="bm-help">Flat colours and plain lines, the way real logos and unit patches are made. Every symbol is a simple drawing you can swap; Copy picture and Save PNG are at the top.</p></div>
      <div class="in-right">
        <section class="bm-card"><h2>Name</h2>
          <div class="bs-grid"><label>Name<input data-d="name" value="${esc(d.name)}" placeholder="e.g. Halvorsen Dynamics"></label><label>Designation<input data-d="desig" value="${esc(d.desig)}" placeholder="e.g. Security Division"></label><label>Code<input data-d="code" value="${esc(d.code)}" placeholder="e.g. HD-07"></label></div></section>
        <section class="bm-card"><h2>Frame</h2><div class="chip-row">${Object.entries(FRAMES).map(([k, v]) => `<button type="button" class="chip ${d.frame === k ? 'on' : ''}" data-frame="${k}">${v}</button>`).join('')}</div>
          <div class="in-toggles"><label class="check"><input type="checkbox" data-t="double" ${d.double ? 'checked' : ''}> Inner line</label><label class="check"><input type="checkbox" data-t="ticks" ${d.ticks ? 'checked' : ''}> Marks</label><label class="check"><input type="checkbox" data-t="panel" ${d.panel ? 'checked' : ''}> Background</label></div>
          <label class="in-w">Line weight <input type="range" data-d="weight" min="2" max="12" step="0.5" value="${d.weight}"></label></section>
        <section class="bm-card"><h2>Symbol</h2><div class="in-syms">${SYM_KEYS.map(k => `<button type="button" class="in-sym ${d.symbol === k ? 'on' : ''}" data-sym="${k}" title="${esc(SYM[k][0])}">${symIcon(k, '#2a2a2a')}</button>`).join('')}</div></section>
        <section class="bm-card"><h2>Colours</h2><div class="chip-row">${Object.entries(SCHEMES).map(([k, v]) => `<button type="button" class="chip in-sch ${d.scheme === k && !d.custom ? 'on' : ''}" data-sch="${k}"><i style="background:${v.bg}"></i><i style="background:${v.main}"></i><i style="background:${v.acc}"></i>${v.name}</button>`).join('')}</div>
          <div class="in-cols"><label>Background <input type="color" data-c="bg" value="${C.bg}"></label><label>Lines <input type="color" data-c="main" value="${C.main}"></label><label>Accent <input type="color" data-c="acc" value="${C.acc}"></label></div></section>
      </div></div>`;
    shot();
  }
  function shot() { const s = $('#in-shot', box); if (s) s.innerHTML = `<img alt="" src="${B.svgURL(insigniaSVG(it.data, 480))}">`; }
  function wire() {
    box.oninput = e => {
      const t = e.target, d = it.data;
      if (t.dataset.d) { d[t.dataset.d] = t.type === 'range' ? +t.value : t.value; if (t.dataset.d === 'name' && (!it.title || it.title === 'Untitled')) it.title = t.value; }
      else if (t.dataset.c) { d.custom = Object.assign({}, d.custom || {}, { [t.dataset.c]: t.value }); $$('.in-sch', box).forEach(b => b.classList.remove('on')); }
      else if (t.dataset.t) d[t.dataset.t] = t.checked;
      else return;
      save(); shot();
    };
    box.onclick = e => {
      const t = e.target.closest('button'); if (!t) return; const d = it.data;
      if (t.dataset.frame) d.frame = t.dataset.frame;
      else if (t.dataset.sym) d.symbol = t.dataset.sym;
      else if (t.dataset.sch) { d.scheme = t.dataset.sch; d.custom = null; }
      else return;
      save(); draw();
    };
  }
  const size = d => (d.name || d.desig || d.code) ? 520 : 400;
  B.editors.insignia = {
    blank, open,
    thumb: item => B.svgURL(insigniaSVG(Object.assign(blank(), item.data || {}), 200)),
    picture: item => { const d = Object.assign(blank(), item.data || {}); return B.svgCanvas(insigniaSVG(d, 1200), 1200, Math.round(1200 * size(d) / 400)); },
    toBook: async item => { const d = Object.assign(blank(), item.data || {}), c = await B.svgCanvas(insigniaSVG(d, 800), 800, Math.round(800 * size(d) / 400));
      return `<p><img src="${c.toDataURL('image/png')}" alt="${esc(item.title || d.name || 'Insignia')}" width="320"></p>`; },
    close: () => { if (box) { box.onclick = null; box.oninput = null; } it = null; box = null; },
    _svg: insigniaSVG, SYMBOLS: SYM_KEYS
  };
})();
